export interface LogoProps {
  markSize?: number | string
  showText?: boolean
  useVectorWordmark?: boolean
  className?: string
  textClassName?: string
  variant?: 'color' | 'white'
}

/**
 * Combined logo (Symbol + Wordmark).
 */
export function Logo({
  markSize = 32,
  showText = true,
  useVectorWordmark = false,
  className = '',
  textClassName = '',
  variant = 'color',
}: LogoProps) {
  return (
    <span
      className={`kk-brand-lockup ${className}`.trim()}
      style={{ display: 'inline-flex', alignItems: 'center', gap: '9px', textDecoration: 'none' }}
    >
      <LogoMark size={markSize} variant={variant} />
      {showText && (
        useVectorWordmark ? (
          <LogoWordmark height={Number(markSize) * 0.65} className={textClassName} />
        ) : (
          <span
            className={textClassName}
            style={{
              fontFamily: 'var(--font-display, "Plus Jakarta Sans", sans-serif)',
              fontWeight: 800,
              fontSize: '1.15rem',
              letterSpacing: '-0.035em',
              lineHeight: 1,
              color: variant === 'white' ? '#ffffff' : 'var(--foreground, #11204f)',
            }}
          >
            keshillohu
          </span>
        )
      )}
    </span>
  )
}

export default Logo
